//! `indicators::ProgressBar`.

use super::cxx_fmt;

/// A single-line progress bar, e.g. `[======================>       ] 75.0%`.
///
/// Field defaults match the C++ constructor: progress `0`, total `100`,
/// width `50`, both the bar and the percentage shown, and the glyphs
/// `[`, `=`, `>`, ` `, `]`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProgressBar {
    progress: i32,
    total: i32,
    width: i32,
    show_percentage: bool,
    /// Gates the whole bar: the opening glyph, the body and the closing glyph.
    show_bar: bool,
    fill: String,
    lead: String,
    remainder: String,
    start: String,
    end: String,
}

impl Default for ProgressBar {
    fn default() -> Self {
        Self::new()
    }
}

impl ProgressBar {
    pub fn new() -> Self {
        ProgressBar {
            progress: 0,
            total: 100,
            width: 50,
            show_percentage: true,
            show_bar: true,
            fill: String::from("="),
            lead: String::from(">"),
            remainder: String::from(" "),
            start: String::from("["),
            end: String::from("]"),
        }
    }

    pub fn set_progress(&mut self, progress: i32) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: i32) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: i32) {
        self.width = width;
    }

    pub fn set_show_percentage(&mut self, show: bool) {
        self.show_percentage = show;
    }

    pub fn set_show_bar(&mut self, show: bool) {
        self.show_bar = show;
    }

    pub fn set_fill(&mut self, fill: &str) {
        self.fill = String::from(fill);
    }

    pub fn set_lead(&mut self, lead: &str) {
        self.lead = String::from(lead);
    }

    pub fn set_remainder(&mut self, remainder: &str) {
        self.remainder = String::from(remainder);
    }

    pub fn set_start(&mut self, start: &str) {
        self.start = String::from(start);
    }

    pub fn set_end(&mut self, end: &str) {
        self.end = String::from(end);
    }

    pub fn progress(&self) -> i32 {
        self.progress
    }

    pub fn total(&self) -> i32 {
        self.total
    }

    pub fn width(&self) -> i32 {
        self.width
    }

    /// The ratio of progress to total, computed in `float` like the C++ source.
    fn ratio(&self) -> f32 {
        self.progress as f32 / self.total as f32
    }

    /// Renders the bar.
    ///
    /// Named `str` to mirror the C++ `str()` member; `to_string` is provided
    /// through [`std::fmt::Display`] as well.
    pub fn str(&self) -> String {
        let mut os = String::new();

        if self.show_bar {
            os.push_str(&self.start);

            // `int completed = progress / total * width` in float arithmetic,
            // truncated toward zero.
            let completed = cxx_fmt::f32_to_i32(self.ratio() * self.width as f32);

            let mut i: i32 = 0;
            while i < self.width {
                if completed > i {
                    os.push_str(&self.fill);
                } else if completed == i {
                    os.push_str(&self.lead);
                } else {
                    os.push_str(&self.remainder);
                }
                i += 1;
            }

            os.push_str(&self.end);
        }

        if self.show_percentage {
            if self.show_bar {
                os.push(' ');
            }
            os.push_str(&cxx_fmt::fixed(self.ratio() as f64 * 100.0, 1));
            os.push('%');
        }

        os
    }
}

impl std::fmt::Display for ProgressBar {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_cpp_test_program() {
        let mut bar = ProgressBar::new();
        bar.set_progress(75);
        bar.set_total(100);
        bar.set_width(30);
        assert_eq!(bar.str(), "[======================>       ] 75.0%");
    }

    #[test]
    fn defaults_match_the_cpp_constructor() {
        let bar = ProgressBar::new();
        assert_eq!(bar.str(), format!("[>{}] 0.0%", " ".repeat(49)));
    }

    #[test]
    fn full_bar_has_no_lead() {
        let mut bar = ProgressBar::new();
        bar.set_progress(100);
        bar.set_total(100);
        bar.set_width(10);
        assert_eq!(bar.str(), "[==========] 100.0%");
    }

    #[test]
    fn zero_width_keeps_the_brackets() {
        let mut bar = ProgressBar::new();
        bar.set_width(0);
        assert_eq!(bar.str(), "[] 0.0%");
    }

    #[test]
    fn hiding_the_bar_drops_the_separator() {
        let mut bar = ProgressBar::new();
        bar.set_show_bar(false);
        assert_eq!(bar.str(), "0.0%");
        bar.set_show_percentage(false);
        assert_eq!(bar.str(), "");
    }
}
=== src/indicators/percentage.rs ===
//! `indicators::Percentage`.

use super::cxx_fmt;

/// Formats a 0.0–1.0 fraction as a percentage with one decimal, e.g. `75.0%`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Percentage {
    value: f32,
}

impl Percentage {
    pub fn new(value: f32) -> Self {
        Percentage { value }
    }

    pub fn set_value(&mut self, value: f32) {
        self.value = value;
    }

    pub fn value(&self) -> f32 {
        self.value
    }

    /// Renders the percentage. Mirrors the C++ `str()` member: the `float` is
    /// widened to `double` before the multiply, then printed with
    /// `std::fixed` and a precision of one.
    pub fn str(&self) -> String {
        let mut s = cxx_fmt::fixed(self.value as f64 * 100.0, 1);
        s.push('%');
        s
    }
}

impl std::fmt::Display for Percentage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_cpp_test_program() {
        assert_eq!(Percentage::new(0.75).str(), "75.0%");
    }

    #[test]
    fn common_fractions() {
        assert_eq!(Percentage::new(0.0).str(), "0.0%");
        assert_eq!(Percentage::new(1.0).str(), "100.0%");
        assert_eq!(Percentage::new(0.5).str(), "50.0%");
        assert_eq!(Percentage::new(0.125).str(), "12.5%");
    }
}
